// src/shared/evidence.ts
import * as fs2 from "fs";
import * as path from "path";
var EVIDENCE_DIR = "evidence";
var ITERATIONS_DIR = "iterations";

class EvidenceCollector {
  basePath;
  constructor(basePath = ".shark") {
    this.basePath = basePath;
  }
  collectEvidence(evidence) {
    const gateDir = path.join(this.basePath, EVIDENCE_DIR, evidence.gate);
    const timestampDir = path.join(gateDir, String(evidence.timestamp));
    this.ensureDir(timestampDir);
    const metaPath = path.join(timestampDir, "evidence.json");
    fs2.writeFileSync(metaPath, JSON.stringify(evidence, null, 2));
    if (evidence.debugLog) {
      fs2.writeFileSync(path.join(timestampDir, "debug.log"), evidence.debugLog);
    }
  }
  collectEvidenceById(gate, id, passed) {
    const ts = Date.now();
    const gateDir = path.join(this.basePath, EVIDENCE_DIR, gate);
    const evidenceDir = path.join(gateDir, `${ts}-${id}`);
    this.ensureDir(evidenceDir);
    const evidence = {
      gate,
      timestamp: ts,
      passed,
      files: [],
      id,
      metadata: { id, source: "gate-engine" }
    };
    fs2.writeFileSync(path.join(evidenceDir, "evidence.json"), JSON.stringify(evidence, null, 2));
  }
  collectDebugLog(iteration, attempt, debugLog) {
    const iterDir = path.join(this.basePath, ITERATIONS_DIR, iteration, "debug-logs");
    this.ensureDir(iterDir);
    const logPath = path.join(iterDir, `attempt-${attempt}.md`);
    fs2.writeFileSync(logPath, debugLog);
  }
  recordIteration(evidence) {
    const iterDir = path.join(this.basePath, ITERATIONS_DIR, evidence.iteration);
    this.ensureDir(iterDir);
    const metaPath = path.join(iterDir, "iteration.json");
    fs2.writeFileSync(metaPath, JSON.stringify(evidence, null, 2));
  }
  getGateEvidence(gate) {
    const gateDir = path.join(this.basePath, EVIDENCE_DIR, gate);
    if (!fs2.existsSync(gateDir))
      return [];
    const evidences = [];
    try {
      const entries = fs2.readdirSync(gateDir);
      for (const entry of entries) {
        const fullPath = path.join(gateDir, entry);
        const subDirEvidence = path.join(fullPath, "evidence.json");
        if (fs2.existsSync(subDirEvidence)) {
          try {
            const content = fs2.readFileSync(subDirEvidence, "utf-8");
            const parsed = safeParseJSON(content);
            if (parsed)
              evidences.push(parsed);
          } catch {
            console.warn("[evidence] invalid evidence file skipped");
          }
          continue;
        }
        if (entry.endsWith(".json")) {
          try {
            const stat = fs2.statSync(fullPath);
            if (stat.isFile()) {
              const content = fs2.readFileSync(fullPath, "utf-8");
              const parsed = safeParseJSON(content);
              if (parsed && parsed.id !== undefined && parsed.passed !== undefined) {
                evidences.push(parsed);
              }
            }
          } catch {}
        }
      }
    } catch {
      console.warn("[evidence] getGateEvidence directory read failed");
    }
    return evidences.sort((a, b) => b.timestamp - a.timestamp);
  }
  getLatestEvidence(gate) {
    const evidences = this.getGateEvidence(gate);
    return evidences[0] || null;
  }
  getIterationLogs(iteration) {
    const logsDir = path.join(this.basePath, ITERATIONS_DIR, iteration, "debug-logs");
    if (!fs2.existsSync(logsDir))
      return [];
    try {
      return fs2.readdirSync(logsDir).filter((f) => f.endsWith(".md")).sort().map((f) => fs2.readFileSync(path.join(logsDir, f), "utf-8"));
    } catch {
      console.warn("[evidence] getIterationLogs failed");
      return [];
    }
  }
  hasRequiredEvidence(gate) {
    const gateName = gate;
    const evidence = this.getGateEvidence(gateName);
    const required = this.getRequiredEvidenceIds(gate);
    const missing = [];
    for (const req of required) {
      const found = evidence.some((e) => e.id === req && e.passed === true);
      if (!found)
        missing.push(req);
    }
    return { passed: missing.length === 0, missing };
  }
  getRequiredEvidenceIds(gate) {
    const requirements = {
      plan: ["spec", "architecture", "error-strategy"],
      build: ["compiled", "source-verified", "deps-installed"],
      test: ["container-test", "unit-test", "browser-test"],
      verify: ["compiled", "source-verified", "deps-installed"],
      audit: ["trident-report", "semantic-firewall-pass", "no-critical", "spec-alignment", "test-authenticity", "theatrical-scan"],
      delivery: ["ship-package", "checksum", "evidence-archive"]
    };
    return requirements[gate] || [];
  }
  hasCompleteEvidence() {
    const gates = ["plan", "build", "verify", "test", "audit", "delivery"];
    return gates.every((gate) => this.getGateEvidence(gate).length > 0);
  }
  ensureDir(dir) {
    if (!fs2.existsSync(dir)) {
      fs2.mkdirSync(dir, { recursive: true });
    }
  }
}

// src/shared/shark-logger.ts
import * as fs3 from "fs";
import * as path2 from "path";
var logFile = null;
function initLogger(basePath) {
  const candidates = [
    basePath,
    process.cwd(),
    "/root/.config/opencode",
    "/tmp"
  ].filter(Boolean);
  const seen = new Set;
  for (const p of candidates) {
    const r = path2.resolve(p);
    if (!r || seen.has(r))
      continue;
    seen.add(r);
    try {
      const logDir = path2.join(r, ".shark");
      fs3.mkdirSync(logDir, { recursive: true });
      const tf = path2.join(logDir, "shark-agent.log");
      fs3.writeFileSync(tf, "", { flag: "a" });
      logFile = tf;
      logInfo("Logger initialized");
      return;
    } catch {
      console.warn("[shark-logger] initLogger failed for path");
      continue;
    }
  }
}
function logInfo(msg) {
  if (!logFile)
    return;
  try {
    const line = `[SharkAgent][INFO] ${msg}`;
    fs3.appendFileSync(logFile, line + `
`);
  } catch (err) {}
}

