function gk(id, gate, rule, verify, sev, layer, links) {
  return {
    id,
    source: "alg-sys",
    sourceFile: "EIE_DESIGN_SPEC.md",
    category: "gate-knowledge",
    rule,
    detectionMethod: "Gate-specific knowledge for " + gate + " gate.",
    fixTemplate: "Follow the rule for " + gate + " gate.",
    conditions: [{ field: "gate", op: "equals", value: gate }],
    bulletTemplate: id + ": " + rule.split(`
`)[0],
    warheadTemplate: "# " + gate + " Gate: " + id + `
` + rule,
    evidenceSpec: { id: id.toLowerCase(), verify, minQuality: 0.95 },
    severity: sev,
    layer,
    links,
    selfVerified: true
  };
}
