function erNode(id, tsCode, rule, fix, bullet, links, severityOverride, layerOverride) {
  return {
    id,
    source: "ts-deep",
    sourceFile: "TypeScript Error Catalog",
    category: "error-recovery",
    rule,
    detectionMethod: `Compiler error ${tsCode ?? "RUNTIME"}: ${rule.split(`
`)[0]}`,
    fixTemplate: fix,
    conditions: tsCode ? [{ field: "errorPattern", op: "matches", value: tsCode }] : [{ field: "errorPattern", op: "matches", value: "runtime" }],
    bulletTemplate: bullet,
    warheadTemplate: `# Error ${tsCode ?? "RUNTIME"}
${rule}
## Fix
${fix}`,
    evidenceSpec: { id: "error-fixed", verify: "exec-tsc", minQuality: 0.9 },
    severity: severityOverride ?? (tsCode ? "warn" : "block"),
    layer: layerOverride ?? (tsCode ? 1 : 4),
    links,
    selfVerified: true
  };
}
