    "class DagScheduler {",
    "  private graph: Map<string, Task[]>; // adjacency",
    '  build() { if (hasCycle(this.graph)) throw new Error("[DAG] cycle detected"); }',
    "  async run(maxWorkers: number): Promise<void> {",
    "    const ready = topologicalReady(this.graph); // parallel-ready nodes",
    "    await runPool(ready, maxWorkers); // resource-constrained",
