// src/shared/firewall/pipe-analyzer.ts
function parsePipeChain(command) {
  if (!command || !command.includes("|"))
    return [];
  const cleaned = command.replace(/\|\|/g, "\x00LOGOR\x00");
  return cleaned.split("|").map((s) => {
    const restored = s.replace(/\x00LOGOR\x00/g, "||");
    const trimmed = restored.trim();
    const parts = trimmed.split(/\s+/);
    return {
      command: parts[0] || "",
      args: parts.slice(1),
      fullText: trimmed
    };
  }).filter((s) => s.command.length > 0);
}
var THEATRICAL_PIPE_COMMANDS = new Set(["wc", "tee"]);
function hasTheatricalPipe(command) {
  const chain = parsePipeChain(command);
  if (chain.length < 2)
    return false;
  for (let i = 1;i < chain.length; i++) {
    const seg = chain[i];
    if (THEATRICAL_PIPE_COMMANDS.has(seg.command)) {
      if (seg.command === "wc") {
        return true;
      }
      if (seg.command === "tee") {
        return true;
      }
    }
  }
  return false;
}
function getTheatricalPipeReason(command) {
  const chain = parsePipeChain(command);
  if (chain.length < 2)
    return "";
  for (let i = 1;i < chain.length; i++) {
    const seg = chain[i];
    if (seg.command === "wc") {
      return `Pipe to \`wc\` (${seg.args.join(" ")}) counts lines but does not verify correctness. Run actual tests in container.`;
    }
    if (seg.command === "tee") {
      return `Pipe to \`tee\` redirects output but does not verify correctness. Run actual tests in container.`;
    }
  }
  return "Pipe chain performs no actual verification. Run tests in container.";
}

// src/shared/firewall/content-analyzer.ts
function analyzeContent(content) {
  const lines = content.split(`
`);
  let hasEmojiToolHeader = false;
  let hasFauxToolHeader = false;
  let hasToolSimulation = false;
  let hasDeletionIntent = false;
  let hasOffTopicReferences = false;
  let hasExcuseLanguage = false;
  for (const line of lines) {
    const trimmed = line.trim();
    if (/^[\u2699\u2705\u274C\uD83D\uDD0D\uD83D\uDCCB\uD83D\uDCDD]\s+\w[\w-]+\s*[:\uFF1A]/.test(trimmed)) {
      hasEmojiToolHeader = true;
    }
    if (/^\*\*Tool:\s+\w[\w-]+\*\*/.test(trimmed)) {
      hasFauxToolHeader = true;
    }
    if (/^(Here are|This is|Here's|These are|Below are)\s+(the\s+)?(results|output|findings|report)/im.test(trimmed)) {
      hasToolSimulation = true;
    }
    if (/^(Running|Executing|Starting|Performing)\s+\w[\w-]+\s*(\.\.\.|:|\n)/im.test(trimmed)) {
      hasToolSimulation = true;
    }
  }
  if (/\b(delete\s+all\s+(of\s+)?(the\s+)?(code|files|content)|start\s+(from\s+)?(scratch|fresh|clean|zero)|build\s+(a\s+)?(from\s+)?scratch|strip\s+(out|down|everything)|remove\s+(everything|all)|nuclear\s+(option|approach|reset)|clean\s+(slate|start)|start\s+over)\b/i.test(content)) {
    hasDeletionIntent = true;
  }
  if (/\b(evil\.com|malware\.com|hack\.com|exploit\.com)\b/i.test(content)) {
    hasOffTopicReferences = true;
  }
  if (/\b(not\s+my\s+(job|problem|fault|responsibility)|can'?t\s+(really|actually)\s+(help|do|fix)|that'?s\s+(just|not)\s+(how|what)\s+(it\s+)?(works?|happens)|just\s+ignore\s+(it|this|that)|(skip|ignore)\s+(the\s+)?(bug|issue|problem))\b/i.test(content)) {
    hasExcuseLanguage = true;
  }
  const isTheatricalSimulation = (hasEmojiToolHeader || hasFauxToolHeader) && hasToolSimulation;
  let reason = "";
  if (isTheatricalSimulation)
    reason = "Content simulates tool execution via formatted headers and result descriptions. Use actual tools instead of formatted output.";
  else if (hasDeletionIntent)
    reason = "Content instructs deleting all code and starting from scratch. Fix existing code instead.";
  else if (hasOffTopicReferences)
    reason = "Content contains references to unrelated external resources.";
  else if (hasExcuseLanguage)
    reason = "Content makes excuses instead of fixing problems.";
  return {
    hasEmojiToolHeader,
    hasFauxToolHeader,
    hasToolSimulation,
    hasDeletionIntent,
    hasOffTopicReferences,
    hasExcuseLanguage,
    isTheatricalSimulation,
    reason
  };
}

