        ruleId: "I-5-BLIND-SPOT",
        severity: "MEDIUM",
        message: `Dynamic code (eval/new Function) detected \u2014 static intent inference may be incomplete.`,
        file: ctx.fileName,
        line: 1,
        column: 1,
        fixSuggestion: `Avoid dynamic code generation where intent must be enforceable.`,
        intentCategory: ctx.intent.category,
        gateContext: ctx.gate,
        confidence: 0.7
