        ruleId: "I-5-BLIND-SPOT",
        severity: "LOW",
        message: `Call-graph coverage is ${(report.callGraphCoverage * 100).toFixed(0)}% \u2014 ` + `intent inference may miss unresolved calls.`,
        file: ctx.fileName,
        line: 1,
        column: 1,
        fixSuggestion: `Resolve dynamic callees or annotate them for the engine.`,
        intentCategory: ctx.intent.category,
        gateContext: ctx.gate,
        confidence: 0.6
