    this.intentClassifier = new IntentClassifier;
    this.intentFsm = new IntentFSM;
    this.streamingBuffer = new StreamingBuffer;
    this.rgeStateMachine = new RGEStateMachine;
    this.slopRemovalEngine = new SlopRemovalEngine(path15.resolve(this.basePath, ".."));
    this.intentEngine = new IntentEngine(path15.resolve(this.basePath, ".."));
