          updateTaskQueue(taskId, `Container test: ${details}`, resultStatus);
          updateEvidenceState(0, `Container test: ${resultStatus} \u2014 ${details}`);
          updateCompactionSurvival("TEST", 0, 0, details);
          updatePostCompactionPrompt(`Container test: ${details}`, "TEST", 0, 0);
