// src/shared/warheads/gate-enforcement.ts
var MAX_GATE_HISTORY = 50;

class GateEnforcement {
  id = "gate-enforcement";
  priority = 2;
  type = "static";
  gateTransitions = 0;
  gateBlocks = 0;
  currentGate = "PLAN";
  currentIteration = "V1.0";
  consecutiveBlocks = {};
  lockedGates = new Set;
  register(hooks) {
    hooks.on("tool.execute.after", (input) => {
      if (!isRecord2(input))
        return;
      const toolInput = input;
      if (!toolInput.tool)
        return;
      const agent = toolInput.agent || "";
      if (!isSharkAgent(agent))
        return;
      if (toolInput.tool === "shark-gate") {
        try {
          const args = toolInput.args;
          if (!isRecord2(args))
            return;
          const action = typeof args.action === "string" ? args.action : "";
          if (action === "advance") {
            this.gateTransitions++;
            const gateName = typeof args.gate === "string" ? args.gate : "";
            const iteration = typeof args.iteration === "string" ? args.iteration : "";
            if (gateName) {
              this.currentGate = gateName.toUpperCase();
            }
            if (iteration) {
              this.currentIteration = iteration;
            }
            if (this.gateTransitions > MAX_GATE_HISTORY) {
              console.warn("[GateEnforcement] Transition count exceeding history limit");
            }
            const xgm = getGateMachineXState();
            if (xgm) {
              xgm.dispatch({ type: "ALLOW", payload: { gateName, iteration }, timestamp: new Date().toISOString() });
            }
          }
          if (action === "evaluate" && args.passed === false) {
            this.gateBlocks++;
            const xgm = getGateMachineXState();
            if (xgm) {
              xgm.dispatch({ type: "BLOCK", payload: { reason: args.reason }, timestamp: new Date().toISOString() });
            }
            const gate = this.currentGate;
            this.consecutiveBlocks[gate] = (this.consecutiveBlocks[gate] || 0) + 1;
            if (this.consecutiveBlocks[gate] >= 3 && !this.lockedGates.has(gate)) {
              this.lockedGates.add(gate);
              if (xgm) {
                xgm.dispatch({ type: "LOCKOUT", payload: { gate, consecutiveBlocks: this.consecutiveBlocks[gate] }, timestamp: new Date().toISOString() });
              }
            }
          }
          if (action === "evaluate" && args.passed === true) {
            const xgm = getGateMachineXState();
            if (xgm) {
              xgm.dispatch({ type: "PASS", payload: { evidenceId: args.evidenceId }, timestamp: new Date().toISOString() });
            }
            const gate = this.currentGate;
            this.consecutiveBlocks[gate] = 0;
            if (this.lockedGates.has(gate)) {
              this.lockedGates.delete(gate);
              if (xgm) {
                xgm.dispatch({ type: "RESTART", payload: { gate }, timestamp: new Date().toISOString() });
              }
            }
          }
        } catch (err) {
          const message = err instanceof Error ? err.message : String(err);
          console.error(`[GateEnforcement] Gate tracking error: ${message}`);
        }
      }
    });
    hooks.on("tool.execute.before", async (input) => {
      if (!isRecord2(input))
        return;
      const ti = input;
      if (!ti.tool)
        return;
      if (!shouldEnforceForAgent(ti.agent))
        return;
      try {
        const gm = getGateManager();
        if (!gm)
          return;
        const gate = gm.getCurrentGate();
        const lexicon = new VerbFrameLexicon;
        if (!lexicon.isAllowedInGate(ti.tool, gate)) {
          this.gateBlocks++;
          throw new EnforcementError(`[GATE] Tool "${ti.tool}" not allowed in ${gate.toUpperCase()} gate. Switch to the appropriate gate first.`);
        }
      } catch (e) {
        if (e instanceof EnforcementError)
          throw e;
      }
    });
  }
  getT0() {
    const lockedInfo = this.lockedGates.size > 0 ? `, LOCKED: ${[...this.lockedGates].join(",")}` : "";
    return `[GATE] Current: ${this.currentGate} | Transitions: ${this.gateTransitions} | Blocks: ${this.gateBlocks}${lockedInfo}`;
  }
}

// src/shared/warheads/container-testing.ts
var MAX_TEST_HISTORY = 20;

class ContainerTesting {
  id = "container-testing";
  priority = 3;
  type = "static";
  containerTestsRun = 0;
  containerTestsPassed = 0;
  register(hooks) {
    hooks.on("tool.execute.after", (input, output) => {
      if (!isRecord2(input))
        return;
      const toolInput = input;
      if (!toolInput.tool)
        return;
      const agent = toolInput.agent || "";
      if (!isSharkAgent(agent))
        return;
      if (toolInput.tool !== "shark-test-runner")
        return;
      try {
        this.containerTestsRun++;
        if (this.containerTestsRun > MAX_TEST_HISTORY) {
          console.warn("[ContainerTesting] Test count exceeding history limit");
        }
        if (!isRecord2(output)) {
          console.error("[ContainerTesting] Test output is not a record");
          return;
        }
        const toolOutput = output;
        const outputStr = toolOutput.output ?? "";
        if (typeof outputStr !== "string" || outputStr.length === 0)
          return;
        const result = safeParseJSON(outputStr);
        if (result && typeof result.overallPassed === "boolean" && result.overallPassed) {
          this.containerTestsPassed++;
        }
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        console.error(`[ContainerTesting] Test result tracking error: ${message}`);
      }
    });
  }
  getT0() {
    const rate = this.containerTestsRun > 0 ? Math.round(this.containerTestsPassed / this.containerTestsRun * 100) : 0;
    return `[CONTAINER] Tests: ${this.containerTestsRun} | Passed: ${this.containerTestsPassed} | Rate: ${rate}%`;
  }
}

