import * as path19 from "path";

// src/evidence-engine/evidence-db.ts
import { Database } from "bun:sqlite";
import * as path18 from "path";
import * as fs19 from "fs";

class EvidenceDB {
  db;
  basePath;
  constructor(basePath) {
    this.basePath = basePath;
    const dbPath = path18.join(basePath, "evidence.db");
    const dir = path18.dirname(dbPath);
    if (!fs19.existsSync(dir))
      fs19.mkdirSync(dir, { recursive: true });
    this.db = new Database(dbPath);
    this.db.run("PRAGMA journal_mode=WAL");
    this.db.run(`
      CREATE TABLE IF NOT EXISTS evidence (
        id TEXT PRIMARY KEY,
        gate TEXT NOT NULL,
        timestamp TEXT NOT NULL,
        passed INTEGER NOT NULL DEFAULT 0,
        rule TEXT,
        findingId TEXT,
        message TEXT,
        chainHash TEXT UNIQUE,
        previousHash TEXT
      )
    `);
    this.db.run("CREATE INDEX IF NOT EXISTS idx_evidence_gate ON evidence(gate)");
    this.db.run("CREATE INDEX IF NOT EXISTS idx_evidence_timestamp ON evidence(timestamp)");
    this.db.run("CREATE INDEX IF NOT EXISTS idx_evidence_rule ON evidence(rule)");
  }
  insert(record) {
    this.db.run(`INSERT OR REPLACE INTO evidence (id, gate, timestamp, passed, rule, findingId, message, chainHash, previousHash)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`, [
      record.id,
      record.gate,
      record.timestamp,
      record.passed ? 1 : 0,
      record.rule || null,
      record.findingId || null,
      record.message || null,
      record.chainHash || null,
      record.previousHash || null
    ]);
  }
  queryByGate(gate, limit = 50) {
    return this.db.query("SELECT * FROM evidence WHERE gate = ? ORDER BY timestamp DESC LIMIT ?").all(gate, limit);
  }
  queryByRule(rule, limit = 50) {
    return this.db.query("SELECT * FROM evidence WHERE rule = ? ORDER BY timestamp DESC LIMIT ?").all(rule, limit);
  }
  queryRecent(limit = 100) {
    return this.db.query("SELECT * FROM evidence ORDER BY timestamp DESC LIMIT ?").all(limit);
  }
  count() {
    const row = this.db.query("SELECT COUNT(*) as c FROM evidence").get();
    return row?.c || 0;
  }
  countByGate(gate) {
    const row = this.db.query("SELECT COUNT(*) as c FROM evidence WHERE gate = ?").get(gate);
    return row?.c || 0;
  }
  verifyChain() {
    const rows = this.db.query("SELECT id, chainHash, previousHash FROM evidence ORDER BY timestamp ASC").all();
    let brokenLinks = 0;
    let previousHash = null;
    for (const row of rows) {
      if (row.previousHash && row.previousHash !== previousHash) {
        brokenLinks++;
      }
      previousHash = row.chainHash;
    }
    return { valid: brokenLinks === 0, brokenLinks, totalBlocks: rows.length };
  }
  close() {
    this.db.close();
  }
}
var _edb = null;
function setEvidenceDB(db) {
  _edb = db;
}
function getEvidenceDB() {
  return _edb;
}

// src/shared/warheads/evidence-pipeline.ts
class EvidencePipeline {
  id = "evidence-pipeline";
  priority = 4;
  type = "static";
  evidenceRecords = 0;
  merkleChainLength = 0;
  merkleIntegrityOk = true;
  validationErrors = 0;
  register(hooks) {
    hooks.on("tool.execute.after", async (input, output) => {
      if (!isRecord2(input))
        return;
      const ti = input;
      if (!shouldEnforceForAgent(ti.agent))
        return;
      this.evidenceRecords++;
      try {
        const gm = getGateManager();
        const sharkBase = gm?.getBasePath() || path19.join(process.cwd(), ".shark");
        const currentGate = gm?.getCurrentGate() || "unknown";
        const evidenceDir = path19.join(sharkBase, "evidence", currentGate, `${Date.now()}-tool-exec-${this.evidenceRecords}`);
        if (!fs20.existsSync(evidenceDir))
          fs20.mkdirSync(evidenceDir, { recursive: true });
        const evidenceFile = path19.join(evidenceDir, "evidence.json");
        fs20.writeFileSync(evidenceFile, JSON.stringify({
          id: `tool-exec-${this.evidenceRecords}`,
          gate: currentGate,
          timestamp: Date.now(),
          source: ti.tool || "unknown",
          passed: true,
          files: []
        }, null, 2));
      } catch (err) {
        console.error("[EvidencePipeline] Failed to write evidence: " + (err instanceof Error ? err.message : String(err)));
      }
      try {
        const edb = getEvidenceDB();
        const currentGate2 = getGateManager()?.getCurrentGate() || "unknown";
        if (edb) {
          edb.insert({
            id: `${currentGate2}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
            gate: currentGate2,
            timestamp: new Date().toISOString(),
            passed: true,
            rule: ti.tool,
            findingId: `tool-exec-${this.evidenceRecords}`,
            message: `Tool executed: ${ti.tool || "unknown"}`
          });
        }
      } catch (err) {
        console.error("[EvidencePipeline] SQLite insert error:", err);
      }
    });
    hooks.on("compacting", () => {
      try {
        const mc = getMerkleChain();
        if (mc) {
          const recent = mc.recent(1e4);
          this.merkleChainLength = recent.length;
          this.merkleIntegrityOk = true;
        }
      } catch (err) {
        this.merkleIntegrityOk = false;
        const message = err instanceof Error ? err.message : String(err);
        console.error(`[EvidencePipeline] Merkle chain read failed: ${message}`);
      }
    });
  }
  getT0() {
    return `[EVIDENCE] Records: ${this.evidenceRecords} | Merkle blocks: ${this.merkleChainLength} | Integrity: ${this.merkleIntegrityOk ? "OK" : "FAILED"}`;
  }
}

