var WRITE_TOOLS2 = new Set(["write", "write_file", "edit", "patch", "create"]);

class TheatricalCodeBlock {
  id = "theatrical-code-block";
  priority = 6;
  type = "static";
  beforeBlocks = 0;
  afterDetections = 0;
  patternsDetected = new Map;
  register(hooks) {
    hooks.on("tool.execute.before", (input, output) => {
      if (!isRecord(input))
        return;
      const toolInput = input;
      if (!toolInput.tool || !WRITE_TOOLS2.has(toolInput.tool))
        return;
      const agent = toolInput.agent || "";
      if (!isSharkAgent(agent))
        return;
      if (!isRecord(output))
        return;
      const args = output.args || {};
      const content = isRecord(args) ? safeGetString(args, "content") || safeGetString(args, "newString") : "";
      if (!content)
        return;
      for (const { pattern, name, severity, correction } of THEATRICAL_PATTERNS) {
        const flags = typeof pattern === "object" && pattern instanceof RegExp ? pattern.flags : "";
        const source = typeof pattern === "object" ? pattern.source : pattern;
        const regex = new RegExp(source, flags);
        if (regex.test(content)) {
          this.beforeBlocks++;
          this.patternsDetected.set(name, (this.patternsDetected.get(name) ?? 0) + 1);
          if (severity === "critical") {
            throw new EnforcementError(`[THEATRICAL CODE] ${name} in ${toolInput.tool}. ${correction}`);
          }
        }
      }
    });
    hooks.on("tool.execute.after", (input, output) => {
      if (!isRecord(input))
        return;
      const toolInput = input;
      if (!toolInput.tool || !WRITE_TOOLS2.has(toolInput.tool))
        return;
      const agent = toolInput.agent || "";
      if (!isSharkAgent(agent))
        return;
      if (!isRecord(output))
        return;
      const toolOutput = output;
      const rawOutput = toolOutput.output ?? toolOutput.result ?? "";
      if (typeof rawOutput !== "string" || rawOutput.length === 0)
        return;
      for (const { pattern, name } of THEATRICAL_PATTERNS) {
        const flags = typeof pattern === "object" && pattern instanceof RegExp ? pattern.flags : "";
        const source = typeof pattern === "object" ? pattern.source : pattern;
        const regex = new RegExp(source, flags);
        if (regex.test(rawOutput)) {
          this.afterDetections++;
          this.patternsDetected.set(name, (this.patternsDetected.get(name) ?? 0) + 1);
        }
      }
    });
  }
  getT0() {
    return `[THEATRICAL] Layer 1 blocks: ${this.beforeBlocks} | Layer 2 detections: ${this.afterDetections}`;
  }
}

