var WRITE_TOOLS3 = new Set(["write", "write_file", "edit", "patch", "create"]);

class StopGuessing {
  id = "stop-guessing";
  priority = 0.5;
  type = "static";
  inferencesBlocked = 0;
  readHistory = new Map;
  writeHistory = new Map;
  filesReadThisSession = 0;
  register(hooks) {
    hooks.on("tool.execute.before", (input, output) => {
      if (!isRecord(input))
        return;
      const toolInput = input;
      if (!toolInput.tool || !WRITE_TOOLS3.has(toolInput.tool))
        return;
      const agent = toolInput.agent || "";
      if (!isSharkAgent(agent))
        return;
      if (!isRecord(output))
        return;
      const args = output.args || {};
      const filePath = typeof args.filePath === "string" ? args.filePath : typeof args.path === "string" ? args.path : "";
      if (!filePath)
        return;
      const lastRead = this.readHistory.get(filePath);
      if (!lastRead || Date.now() - lastRead > 300000) {
        this.inferencesBlocked++;
      }
    });
  }
  trackFileRead(filePath) {
    this.readHistory.set(filePath, Date.now());
    this.filesReadThisSession = this.readHistory.size;
  }
  getReadHistory() {
    return this.readHistory;
  }
  trackWrite(filePath) {
    this.writeHistory.set(filePath, Date.now());
  }
  getWriteHistory() {
    return this.writeHistory;
  }
  wasFileRead(filePath, maxAgeMs = 300000) {
    const lastRead = this.readHistory.get(filePath);
    return lastRead !== undefined && Date.now() - lastRead <= maxAgeMs;
  }
  incrementBlocked() {
    this.inferencesBlocked++;
  }
  getT0() {
    return `[STOP-GUESSING] Inferences: ${this.inferencesBlocked} | Files read: ${this.filesReadThisSession}`;
  }
}

