import * as path21 from "path";
import * as fs22 from "fs";
async function copyDir(src, dest) {
  await fs22.promises.mkdir(dest, { recursive: true });
  const entries = await fs22.promises.readdir(src, { withFileTypes: true });
  for (const entry of entries) {
    const srcPath = path21.join(src, entry.name);
    const destPath = path21.join(dest, entry.name);
    if (entry.isDirectory()) {
      await copyDir(srcPath, destPath);
    } else if (entry.isFile()) {
      await fs22.promises.copyFile(srcPath, destPath);
    }
  }
}
