  "CHANGELOG.md",
  "DEBUG_LOG.md",
  "SoC_PRESERVATION.md",
  "POST-COMPACTION_PROMPT.md",
  "BUILD_STATE.md",
  "DECISION_CHAIN.md",
  "EVIDENCE_STATE.md",
  "TASK_QUEUE.md"
