  checks.gateChainCorrect = GATE_CHAIN.length === correctChain.length && GATE_CHAIN.every((g, i) => g === correctChain[i]);
  if (!checks.gateChainCorrect) {
    issues.push(`GATE_CHAIN order is wrong: expected ${correctChain.join("\u2192")}, got ${GATE_CHAIN.join("\u2192")}`);
  }
