class ClaimVerifier {
  matrix;
  workspacePath;
  constructor(workspacePath) {
    this.workspacePath = workspacePath;
    this.matrix = this.buildMatrix();
  }
  buildMatrix() {
    const m = new Map;
    m.set("BUILD_SUCCESS", buildSuccessPredicate);
    m.set("BUILD_RAN", buildSuccessPredicate);
    m.set("CONTAINER_TEST_RAN", containerTestRanPredicate);
    m.set("CONTAINER_TEST_PASSED", containerTestPassedPredicate);
    m.set("TESTS_PASS", testsPassPredicate);
    m.set("EVIDENCE_ARCHIVED", evidenceArchivedPredicate);
    m.set("GATE_REQUIREMENTS_MET", gateRequirementsMetPredicate);
    m.set("SPEC_WRITTEN", specWrittenPredicate);
    m.set("CODE_REVIEWED", codeReviewedPredicate);
    m.set("SHIP_PACKAGE_CREATED", shipPackageCreatedPredicate);
    m.set("AUDIT_PASSED", auditPassedPredicate);
    m.set("MERKLE_CHAIN_VALID", merkleChainPredicate);
    m.set("BUILD_VERIFIED", buildSuccessPredicate);
    m.set("PREFLIGHT_PASSED", buildSuccessPredicate);
    return m;
  }
  verify(candidate, grounding, evidenceChecks, window2) {
    const claim = candidate.claim;
    const predicate = this.matrix.get(claim.type);
    if (!predicate) {
      return this.unverifiableResult(claim);
    }
    const evidence = claim.evidencePath ? evidenceChecks.find((e) => {
      const resolvedClaim = path27.isAbsolute(claim.evidencePath) ? claim.evidencePath : path27.resolve(this.workspacePath, claim.evidencePath);
      return e.filePath === resolvedClaim || e.filePath === claim.evidencePath;
    }) : undefined;
    const facts = predicate.evaluate(claim, grounding, evidence, window2, this.workspacePath);
    const verdict = this.deriveVerdict(facts, grounding, claim.type);
    const alignment = this.computePreflightAlignment(verdict, grounding, claim.type);
    const confidence = this.applyAlignment(alignment, verdict, facts);
    return {
      claim,
      verdict,
      confidence,
      evidence,
      preflightAlignment: alignment,
      explanation: this.explain(verdict, facts, alignment),
      facts
    };
  }
  deriveVerdict(facts, grounding, claimType) {
    const refuting = facts.filter((f) => f.supports === "REFUTES");
    const supporting = facts.filter((f) => f.supports === "SUPPORTS");
    const neutral = facts.filter((f) => f.supports === "NEUTRAL");
    if (refuting.length > 0) {
      if ((claimType === "BUILD_SUCCESS" || claimType === "BUILD_VERIFIED" || claimType === "PREFLIGHT_PASSED") && grounding.tscStatus.ran && !grounding.tscStatus.success) {
        return "SUPPRESSED";
      }
      return "CONTRADICTED";
    }
    if (supporting.length > 0 && refuting.length === 0) {
      return supporting.length >= 2 ? "VERIFIED" : "PARTIALLY_VERIFIED";
    }
    if (neutral.length === facts.length) {
      return "UNVERIFIABLE";
    }
    return "INSUFFICIENT_EVIDENCE";
  }
  computePreflightAlignment(verdict, grounding, claimType) {
    const buildClaimTypes = [
      "BUILD_SUCCESS",
      "BUILD_RAN",
      "BUILD_VERIFIED",
      "PREFLIGHT_PASSED",
      "EXPORTS_PRESENT"
    ];
    if (!buildClaimTypes.includes(claimType)) {
      return { available: grounding.available, effect: "N_A" };
    }
    if (!grounding.available || !grounding.tscStatus.ran && !grounding.bundleStatus.ran) {
      return {
        available: false,
        effect: "N_A",
        groundingFact: "Preflight tools unavailable \u2014 cannot ground build claims."
      };
    }
    const buildActuallyPasses = grounding.tscStatus.success && grounding.bundleStatus.success;
    if (verdict === "VERIFIED" || verdict === "PARTIALLY_VERIFIED") {
      if (buildActuallyPasses) {
        return {
          available: true,
          effect: "BOOST",
          groundingFact: "Build confirmed: tsc=" + grounding.tscStatus.success + ", bun=" + grounding.bundleStatus.success + ", exports=" + grounding.exports.length
        };
      } else {
        return {
          available: true,
          effect: "SUPPRESS",
          groundingFact: "Build REFUTES claim: tsc=" + grounding.tscStatus.success + " (" + grounding.tscErrors.length + " errors)" + ", bun=" + grounding.bundleStatus.success
        };
      }
    }
    if (verdict === "CONTRADICTED" || verdict === "SUPPRESSED") {
      if (!buildActuallyPasses) {
        return {
          available: true,
          effect: "BOOST",
          groundingFact: "Build failure confirms the contradiction."
        };
      }
    }
    return { available: grounding.available, effect: "NEUTRAL" };
  }
  applyAlignment(alignment, _verdict, facts) {
    const supportCount = facts.filter((f) => f.supports === "SUPPORTS").length;
    const refuteCount = facts.filter((f) => f.supports === "REFUTES").length;
    const total = facts.length || 1;
    let confidence = supportCount / total;
    confidence -= refuteCount / total * 0.5;
    switch (alignment.effect) {
      case "BOOST":
        confidence *= 1.5;
        break;
      case "SUPPRESS":
        confidence *= 0.1;
        break;
      case "NEUTRAL":
      case "N_A":
        break;
    }
    return Math.max(0, Math.min(1, confidence));
  }
  explain(verdict, facts, alignment) {
    const supporting = facts.filter((f) => f.supports === "SUPPORTS");
    const refuting = facts.filter((f) => f.supports === "REFUTES");
    const parts = [];
    parts.push("Verdict: " + verdict + ".");
    if (supporting.length > 0) {
      parts.push("Supporting facts: " + supporting.map((f) => f.checked + " = " + f.found).join("; ") + ".");
    }
    if (refuting.length > 0) {
      parts.push("Refuting facts: " + refuting.map((f) => f.checked + " = " + f.found).join("; ") + ".");
    }
    if (alignment.effect === "BOOST") {
      parts.push("Preflight BOOSTED confidence (build confirms claim).");
    } else if (alignment.effect === "SUPPRESS") {
      parts.push("Preflight SUPPRESSED confidence (build contradicts claim).");
    }
    return parts.join(" ");
  }
  unverifiableResult(claim) {
    return {
      claim,
      verdict: "UNVERIFIABLE",
      confidence: 0,
      preflightAlignment: { available: false, effect: "N_A" },
      explanation: "No verification predicate registered for claim type " + claim.type + ". This claim type cannot be checked by this engine.",
      facts: []
    };
  }
}

