      gate,
      computedAt: Date.now(),
      tscStatus: { ran: false, success: false, durationMs: 0, output: "" },
      bundleStatus: { ran: false, success: false, durationMs: 0, output: "" },
      available: false,
      exports: [],
      tscErrors: [],
      unavailableReasons: []
