  if (!fs40.existsSync(warheadDir))
    return null;
  let files;
  try {
    files = fs40.readdirSync(warheadDir).filter((f) => f.endsWith(".md")).sort().reverse();
  } catch {
    return null;
  }
  if (files.length === 0)
    return null;
  const filePath = path40.join(warheadDir, files[0]);
