      const isSourceChange = (lowerPath.includes("/src/") || lowerPath.includes("\\src\\")) && (lowerPath.endsWith(".ts") || lowerPath.endsWith(".js") || lowerPath.endsWith(".tsx") || lowerPath.endsWith(".jsx"));
