function createPostWriteAudit(firewall, quarantineDir) {
  return async (input, output) => {
    const currentAgent = getCurrentAgent();
    if (!currentAgent || !isSharkAgent(currentAgent))
      return;
    const toolName = String(input?.tool || "");
    const AUDITED_TOOLS = ["write", "edit", "write_file", "mcp_write_file", "mcp_edit", "patch", "mcp_patch", "create", "mcp_create"];
    if (!AUDITED_TOOLS.includes(toolName))
      return;
    const args = input?.args || output?.args || {};
    const filePath = typeof args.filePath === "string" ? args.filePath : typeof args.path === "string" ? args.path : "";
    const fileExt = path46.extname(filePath).toLowerCase();
    const isTsFile = fileExt === ".ts" || fileExt === ".tsx";
    const isMdFile = fileExt === ".md" || fileExt === ".mdx";
    const effectiveRules = isTsFile ? POST_WRITE_RULES : isMdFile ? CONTENT_ONLY_RULES : POST_WRITE_RULES.filter((r) => !TS_AST_ONLY_RULES.has(r.name));
    if (isMdFile) {
      let mdContent = "";
      try {
        if (filePath && fs45.existsSync(filePath)) {
          mdContent = fs45.readFileSync(filePath, "utf-8");
        } else {
          mdContent = typeof args.content === "string" ? args.content : typeof args.newString === "string" ? args.newString : "";
        }
      } catch {}
      const mdSize = mdContent.length;
      const hasSections = /^#{1,3}\s+\w+/m.test(mdContent);
      const hasCodeBlock = /```[\s\S]*?```/m.test(mdContent);
      const hasBullets = /^[-*+]\s+/m.test(mdContent);
      const isTheatrical = mdSize < 500 && !hasSections && !hasCodeBlock && !hasBullets && /^(i'?ll|just|create|implement|do it|make it)/i.test(mdContent.trim());
      if (isTheatrical) {
        logInfo(`[PostWriteAudit] Theatrical .md file detected (${mdSize} bytes, no structure) \u2014 warning only, no quarantine for docs`);
        if (!Array.isArray(output.system))
          output.system = [];
        output.system.push("[SEMANTIC-FIREWALL] Theatrical .md file: content lacks structure. Consider adding sections and details.");
      } else {
        logInfo(`[PostWriteAudit] .md file passed content check: ${mdSize} bytes, hasSections=${hasSections}, hasCodeBlock=${hasCodeBlock}`);
      }
      return;
    }
    const result = firewall.analyze("post-write", effectiveRules);
    const findings = result.diagnostics;
    const currentGate = getGateManager()?.getCurrentGate() || "plan";
    const writeToSrcAllowed = isAllowed(currentGate, "writeToSrc");
    const noEmptyCatchRecognizesRethrow = true;
    let quarantined = false;
    for (const finding of findings) {
      const findingFile = finding.file;
      if (findingFile && filePath && !filePath.includes(path46.basename(findingFile))) {
        logInfo(`[PostWriteAudit] Skipping cross-file finding: ${finding.rule} in ${findingFile} (wrote: ${filePath})`);
        continue;
      }
      if (writeToSrcAllowed && (finding.rule === "scope-violation" || finding.rule === "SF-SCOPE-VIOLATION" || finding.rule === "ZONE_VIOLATION")) {
        logInfo(`[PostWriteAudit] Skipping scope-violation during ${currentGate} gate: ${finding.rule}`);
        continue;
      }
      if (noEmptyCatchRecognizesRethrow && finding.rule === "no-empty-catch") {
        if (filePath && fs45.existsSync(filePath)) {
          try {
            const fileContent = fs45.readFileSync(filePath, "utf-8");
            if (/catch\s*\([^)]*\)\s*\{[\s\S]*?throw\s+/.test(fileContent)) {
              logInfo(`[PostWriteAudit] Skipping no-empty-catch: file has rethrow in catch block (legitimate handling)`);
              continue;
            }
          } catch {}
        }
      }
      if (finding.severity === "CRITICAL" || finding.severity === "HIGH") {
        if (!quarantined && filePath) {
          quarantined = quarantineFile(filePath, finding.rule || "UNKNOWN", finding.severity);
        } else if (!filePath) {
          logInfo(`[PostWriteAudit] WARNING: CRITICAL/HIGH finding (${finding.rule}) detected but no filePath \u2014 cannot quarantine.`);
        }
      }
    }
    const criticalCount = findings.filter((d) => d.severity === "CRITICAL" || d.severity === "HIGH").length;
    if (findings.length > 0) {
      try {
        const logPath = path46.join(quarantineDir, "evidence", "enforcement", "sf-audit-" + Date.now() + ".json");
        fs45.mkdirSync(path46.dirname(logPath), { recursive: true });
        fs45.writeFileSync(logPath, JSON.stringify({ timestamp: new Date().toISOString(), toolName, filePath, phase: "post-write", total: findings.length, critical: criticalCount, quarantined, diagnostics: findings }, null, 2));
      } catch (logErr) {
        logInfo("[PostWriteAudit] log failed: " + logErr);
      }
    }
    const warnings = findings.filter((d) => d.severity === "MEDIUM");
    if (warnings.length > 0 && output) {
      for (const w of warnings) {
        if (!output.system)
          output.system = [];
        output.system.push("[SEMANTIC-FIREWALL] " + w.severity + ": " + w.message);
      }
    }
  };
}

