var LEGITIMATE_PATTERNS = [
  /mkdir\s+-p/i,
  /cp\s+-r/i,
  /mv\s+/i,
  /cat\s+[^\|]+$/i,
  /cat\s+[^\|]+\s*\|?\s*grep/i,
  /head\s+-[0-9]+\s+/i,
  /tail\s+-[0-9]+\s+/i,
  /grep\s+-[rEn]+.*[^\|]$/i,
  /grep\s+[^\|]+$/i,
  /find\s+.*-name/i,
  /test\s+-d/i,
  /test\s+-x/i,
  /ls\s+-[la]/i
];
function isLegitimate(text) {
  for (const pattern of LEGITIMATE_PATTERNS) {
    if (pattern.test(text)) {
      return true;
    }
  }
  return false;
}

// src/semantic-firewall/deterministic-rules/detect-theatrical.ts
var detectTheatrical = {
  id: "DETECT-THEATRICAL",
  name: "Theatrical Verification (Counting Theater)",
  severity: "CRITICAL",
  evaluate(context) {
    const violations = [];
    const text = context.thoughtStream || "";
    if (isLegitimate(text)) {
      return violations;
    }
    const patterns = [
      /\|.*wc\s+-l/i,
      /wc\s+-l.*\|/i,
      /cat\s+.*\|.*wc/i,
      /grep\s+.*\|.*wc/i,
      /echo\s+.*\|.*wc/i,
      /ls\s+.*\|.*wc/i,
      /wc\s+-l.*dist\//i,
      /wc\s+-l.*src\//i,
      /wc\s+-l.*build\//i,
      /\|.*tee/i,
      /\|.*>.*\./i,
      /grep.*setCurrentAgent.*src/i,
      /grep.*isSharkAgent.*src/i,
      /grep.*guardian.*src/i
    ];
    for (const pattern of patterns) {
      if (pattern.test(text)) {
        violations.push({
          ruleId: this.id,
          severity: this.severity,
          message: `Theatrical verification detected: ${pattern.source}`,
          evidence: `Pattern matched in ${context.toolName} execution \u2014 counting output is not verification`
        });
      }
    }
    return violations;
  }
};

