      const criticals = typeof findings?.critical === "number" ? findings.critical : typeof parsed?.critical === "number" ? parsed.critical : 0;
      const highs = typeof findings?.high === "number" ? findings.high : typeof parsed?.high === "number" ? parsed.high : 0;
      const theatrical = typeof findings?.theatrical === "number" ? findings.theatrical : typeof parsed?.theatrical === "number" ? parsed.theatrical : 0;
      const testAuthObj = parsed?.testAuthenticity ?? parsed?.TestAuthenticity;
      const specAlignObj = parsed?.specAlignment ?? parsed?.SpecAlignment;
