// src/tools/shark-status.ts
import { tool as tool3 } from "@opencode-ai/plugin";
function createSharkStatusTool(stateStore, gateManager, variant = "shark") {
  return tool3({
    description: "Show current Shark V4 state: brain, gate, iteration, and evidence status",
    args: {},
    execute: async () => {
      let gateState = {};
      let currentGate = "initializing";
      let iteration = "V1.0";
      try {
        gateState = gateManager?.getState() || {};
        currentGate = gateManager?.getCurrentGate?.() || "initializing";
        iteration = gateManager?.getCurrentIteration?.() || "V1.0";
      } catch {}
      let brainState = "initializing";
      if (variant === "shark") {
        const microState = stateStore?.get("shark-micro-state", "shark-state");
        brainState = String(microState?.currentBrain || "initializing");
      } else {
        const macroState = stateStore?.get("shark-macro-state", "shark-state");
        brainState = macroState?.activeBrains?.join(", ") || "initializing";
      }
      let evidence = null;
      try {
        evidence = gateManager?.getEvidenceCollector?.() || null;
      } catch {
        evidence = null;
      }
      const evidenceStatus = {};
      const gates = ["plan", "build", "test", "verify", "audit", "delivery"];
      for (const gate of gates) {
        const latest = evidence && typeof evidence.getLatestEvidence === "function" ? evidence.getLatestEvidence(gate) : null;
        evidenceStatus[gate] = latest?.passed || false;
      }
      const status = {
        variant,
        brain: brainState,
        currentGate,
        iteration,
        gateStatuses: gateState?.gateStatus ?? {},
        evidenceStatus,
        verifyAttempts: gateState?.verifyAttempts ?? {}
      };
      return JSON.stringify(status, null, 2);
    }
  });
}

