function createSharkTestRunnerTool() {
  return tool5({
    description: "Run container-aware mechanical test suite for shark agent. Produces ContainerTestResult.json for ship gate evidence.",
    args: {
      action: z3.enum(["run", "status", "report"]).describe("Action: run tests, check status, or generate report"),
      buildId: z3.string().optional().describe("Build ID to report")
    },
    execute: async (args, _ctx) => {
      const { action, buildId } = args;
      if (action === "status") {
        return JSON.stringify({
          status: "ready",
          containerAware: true,
          testCount: TEST_SUITE.length,
          tests: TEST_SUITE.map((t3) => t3.name)
        });
      }
      if (action === "run" || action === "report") {
        const id = buildId || `shark-v5.1-${new Date().toISOString().slice(0, 10)}`;
        const results = [];
        for (const testDef of TEST_SUITE) {
          try {
            const result = await testDef.test();
            results.push(result);
          } catch (error) {
            results.push({
              name: testDef.name,
              passed: false,
              output: `Test error: ${error instanceof Error ? error.message : "Unknown"}`,
              timestamp: Date.now()
            });
          }
        }
        const passedTests = results.filter((r2) => r2.passed).length;
        const totalTests = results.length;
        const passRate = totalTests > 0 ? passedTests / totalTests : 0;
        const overallPassed = passRate >= 0.9;
        const suiteResult = {
          suite: "shark-agent-v5.1-container",
          timestamp: Date.now(),
          buildId: id,
          tests: results,
          overallPassed,
          totalTests,
          passedTests,
          failedTests: totalTests - passedTests,
          passRate
        };
        const evidenceDirs = [
          path51.join(getBasePath(), ".shark", "evidence", "test"),
          path51.join(getBasePath(), ".shark", "evidence", "delivery"),
          path51.join(getBasePath(), ".shark", "evidence", "verify")
        ];
        for (const dir of evidenceDirs) {
          try {
            fs50.mkdirSync(dir, { recursive: true });
            fs50.writeFileSync(path51.join(dir, "ContainerTestResult.json"), JSON.stringify(suiteResult, null, 2));
          } catch (_err) {
            console.warn("[shark-test-runner] evidence dir not writable:", dir, _err instanceof Error ? _err.message : String(_err));
          }
        }
        let summary = `Test suite: ${id}
`;
        summary += `Results: ${passedTests}/${totalTests} passed (${Math.round(passRate * 100)}%)

`;
        for (const result of results) {
          summary += `${result.passed ? "\u2713" : "\u2717"} ${result.name}
`;
          summary += `  \u2192 ${result.output}
`;
        }
        summary += `
Overall: ${overallPassed ? "PASS" : "FAIL"}`;
        if (overallPassed) {
          summary += `
[Ship gate evidence collected]`;
        }
        return summary;
      }
      return JSON.stringify({ error: "Unknown action. Use: run, status, or report" });
    }
  });
}

