// src/tools/checkpoint-history.ts
import { tool as tool10 } from "@opencode-ai/plugin";
import { z as z7 } from "zod";
import * as path56 from "path";
import * as fs55 from "fs";
async function copyDir2(src, dest) {
  await fs55.promises.mkdir(dest, { recursive: true });
  const entries = await fs55.promises.readdir(src, { withFileTypes: true });
  for (const entry of entries) {
    const srcPath = path56.join(src, entry.name);
    const destPath = path56.join(dest, entry.name);
    if (entry.isDirectory()) {
      await copyDir2(srcPath, destPath);
    } else if (entry.isFile()) {
      await fs55.promises.copyFile(srcPath, destPath);
    }
  }
}
function createCheckpointHistoryTool() {
  return tool10({
    description: "List preserved phase versions and restore to a previous phase",
    args: {
      action: z7.enum(["list", "journey", "restore"]).describe("Action: list phases, show journey timeline, or restore a phase"),
      phase: z7.string().optional().describe("Phase name to restore (e.g. v4.9_phase2_build)")
    },
    execute: async (args) => {
      const { action, phase } = args;
      const cwd = process.cwd();
      const versionsDir = path56.join(cwd, ".shark", "versions");
      if (action === "list") {
        try {
          const entries = await fs55.promises.readdir(versionsDir, { withFileTypes: true });
          const phases = entries.filter((e2) => e2.isDirectory()).map((e2) => e2.name).sort();
          if (phases.length === 0) {
            return JSON.stringify({ phases: [], message: "No preserved phases found." }, null, 2);
          }
          const details = phases.map((p5) => {
            const versionPath = path56.join(versionsDir, p5, "VERSION.md");
            let versionInfo = "N/A";
            try {
              versionInfo = fs55.readFileSync(versionPath, "utf-8").split(`
`)[0]?.replace("# ", "") || "N/A";
            } catch {
              console.warn("[checkpoint-history] versionInfo read failed");
            }
            return { phase: p5, info: versionInfo };
          });
          return JSON.stringify({ phases: details }, null, 2);
        } catch {
          console.warn("[checkpoint-history] list phases failed");
          return JSON.stringify({ phases: [], message: "No .shark/versions directory found." }, null, 2);
        }
      }
      if (action === "journey") {
        const journeyPath = path56.join(cwd, ".shark", "BUILD_JOURNEY.md");
        try {
          const content = await fs55.promises.readFile(journeyPath, "utf-8");
          return content;
        } catch {
          console.warn("[checkpoint-history] journey file read failed");
          return `# Shark Build Journey

No build journey recorded yet.`;
        }
      }
      if (action === "restore") {
        if (!phase) {
          return JSON.stringify({ error: "Phase name required for restore action" });
        }
        const phaseDir = path56.join(versionsDir, phase);
        try {
          await fs55.promises.access(phaseDir);
        } catch {
          console.warn("[checkpoint-history] phase access failed");
          return JSON.stringify({ error: `Phase '${phase}' not found` });
        }
        const restored = [];
        for (const subdir of ["src", "dist", "compaction_survival"]) {
          const srcDir = path56.join(phaseDir, subdir);
          const destDir = path56.join(cwd, subdir);
          try {
            await fs55.promises.rm(destDir, { recursive: true, force: true });
            await copyDir2(srcDir, destDir);
            restored.push(subdir);
          } catch {
            console.warn("[checkpoint-history] restore subdir failed: " + subdir);
          }
        }
        return JSON.stringify({
          restored: true,
          phase,
          directories: restored,
          message: `Restored ${restored.join(", ")} from phase '${phase}'`
        }, null, 2);
      }
      return JSON.stringify({ error: "Unknown action" });
    }
  });
}

