import * as path67 from "path";
class ExecutionContext {
  editHistory = [];
  _currentAgent = "";
  _projectRoot = "";
  constructor(sharkProjectRoot = "") {
    this._projectRoot = sharkProjectRoot || process.env.SHARK_PROJECT_ROOT || process.cwd();
  }
  get currentGate() {
    return getGateManager()?.getCurrentGate() || "plan";
  }
  get currentAgent() {
    return this._currentAgent;
  }
  get projectRoot() {
    return this._projectRoot;
  }
  setAgent(agent) {
    this._currentAgent = agent;
  }
  getProjectRoot() {
    return this._projectRoot;
  }
  getAgent() {
    return this._currentAgent;
  }
  recordEdit(toolName, filePath) {
    this.editHistory.push({ toolName, filePath, timestamp: Date.now(), agentName: this._currentAgent });
    if (this.editHistory.length > 100)
      this.editHistory.shift();
  }
  isSharkProjectFile(filePath) {
    if (!this._projectRoot)
      return false;
    const resolvedPath = path67.resolve(filePath);
    return resolvedPath.startsWith(this._projectRoot);
  }
  hasRecentEdit() {
    const recent = this.editHistory.filter((e2) => Date.now() - e2.timestamp < 60000).filter((e2) => e2.toolName === "edit" || e2.toolName === "write");
    return recent.length > 0;
  }
  isOperationAllowedForGate(toolName, _targetFile) {
    const gate = this.currentGate;
    if (gate === "build") {
      if (toolName === "bash")
        return true;
      if (toolName === "write" || toolName === "edit")
        return true;
    }
    if (gate === "test") {
      if (toolName === "shark-test-runner")
        return true;
      if (toolName === "shark-browser-test")
        return true;
    }
    return false;
  }
}

